def validate_raw(topics, name):
    assert len(topics) == 100, f"Expected 100 {name} topics, got {len(topics)}"
    seen_titles = set()
    for t in topics:
        title, subj, sys_field, hallmark, ref_label, ref_url = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {title}"
        assert sys_field in TAXONOMY_SYSTEMS, f"Invalid system {sys_field} in {title}"
        assert ref_url.startswith("https://"), f"Invalid ref_url in {title}"
        assert len(hallmark) >= 20, f"Hallmark too short in {title}"
        assert title not in seen_titles, f"Duplicate title {title}"
        seen_titles.add(title)
    print(f"Validated 100 {name} topics successfully.")

if __name__ == "__main__":
    validate_raw(NEET_RAW, "NEET PG")
    validate_raw(MRCP_RAW, "MRCP")
    validate_raw(FCPS_RAW, "FCPS")
    
    out_path = "scripts/mega53_topics_b.py"
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Generated Topics for Mega-Batch 53 Part B\n\n")
        f.write(f"NEET_TOPICS = {repr(NEET_RAW)}\n\n")
        f.write(f"MRCP_TOPICS = {repr(MRCP_RAW)}\n\n")
        f.write(f"FCPS_TOPICS = {repr(FCPS_RAW)}\n")
    print(f"Wrote {out_path} successfully.")
